import json
import subprocess
import argparse
import threading
from queue import Queue
from collections import defaultdict

def run_job(job_id, command, results_queue):
    try:
        process = subprocess.Popen(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate()
        result = {
            "stdout": stdout,
            "stderr": stderr,
            "returncode": process.returncode
        }
        results_queue.put((job_id, result))
    except Exception as e:
        results_queue.put((job_id, {
            "stdout": "",
            "stderr": str(e),
            "returncode": -1
        }))

def worker(results_queue, max_concurrent):
    while True:
        job_id, command = results_queue.get()
        if job_id == "STOP":
            break
        run_job(job_id, command, results_queue)
        results_queue.task_done()

def main():
    parser = argparse.ArgumentParser(description='Run jobs concurrently and save results.')
    parser.add_argument('jobs_file', help='Path to the jobs JSON file')
    parser.add_argument('results_file', help='Path to the results JSON file')
    args = parser.parse_args()

    with open(args.jobs_file, 'r') as f:
        jobs = json.load(f)

    existing_results = {}
    if args.results_file.exists():
        with open(args.results_file, 'r') as f:
            existing_results = json.load(f)

    results_queue = Queue()
    threads = []
    max_concurrent = 4

    for job in jobs:
        if job["id"] in existing_results:
            continue
        results_queue.put((job["id"], job["command"]))

    for _ in range(max_concurrent):
        t = threading.Thread(target=worker, args=(results_queue, max_concurrent))
        t.start()
        threads.append(t)

    results_queue.join()

    for t in threads:
        results_queue.put(("STOP", None))
        t.join()

    new_results = {}
    for job in jobs:
        job_id = job["id"]
        if job_id not in existing_results:
            job_id, result = results_queue.get()
            new_results[job_id] = result

    final_results = {**existing_results, **new_results}

    with open(args.results_file, 'w') as f:
        json.dump(final_results, f, indent=2)

if __name__ == "__main__":
    import os
    from pathlib import Path
    main()

import json
import subprocess
import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Dict, Any

def run_job(job_id: str, command: str) -> Dict[str, Any]:
    try:
        process = subprocess.Popen(
            command.split(),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            shell=False
        )
        stdout, stderr = process.communicate()
        return {
            "id": job_id,
            "stdout": stdout.strip(),
            "stderr": stderr.strip(),
            "returncode": process.returncode
        }
    except Exception as e:
        return {
            "id": job_id,
            "stdout": "",
            "stderr": str(e),
            "returncode": -1
        }

def process_jobs(jobs_file_path: str) -> None:
    with open(jobs_file_path, 'r') as f:
        jobs = json.load(f)

    results = {}
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(run_job, job["id"], job["command"]): job["id"] for job in jobs}
        for future in as_completed(futures):
            job_id = futures[future]
            try:
                results[job_id] = future.result()
            except Exception as e:
                results[job_id] = {
                    "id": job_id,
                    "stdout": "",
                    "stderr": str(e),
                    "returncode": -1
                }

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Run jobs concurrently and capture output.")
    parser.add_argument("jobs_file", help="Path to the JSON jobs file")
    args = parser.parse_args()
    process_jobs(args.jobs_file)

import json
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed

def run_job(job_id, command):
    try:
        process = subprocess.Popen(
            command.split(),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate()
        return {
            "stdout": stdout.strip(),
            "stderr": stderr.strip(),
            "returncode": process.returncode
        }
    except Exception as e:
        return {
            "stdout": "",
            "stderr": str(e),
            "returncode": -1
        }

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_jobs.py <json_file>", file=sys.stderr)
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        jobs = json.load(f)

    results = {}

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(run_job, job_id, cmd): job_id for job_id, cmd in jobs.items()}
        for future in as_completed(futures):
            job_id = futures[future]
            try:
                results[job_id] = future.result()
            except Exception as e:
                results[job_id] = {
                    "stdout": "",
                    "stderr": str(e),
                    "returncode": -1
                }

    print(json.dumps(results))

if __name__ == "__main__":
    main()
